package main

import (
	"bytes"
	"os"
	"os/exec"
)

func convertPDFToText(pdfPath string) (string, error) {
	cmd := exec.Command("pdftotext", pdfPath, "-")
	var out bytes.Buffer
	cmd.Stdout = &out
	err := cmd.Run()
	return out.String(), err
}

func main() {
	text, err := convertPDFToText("sample.pdf")
	if err != nil {
		println("Error converting PDF:", err.Error())
	} else {
		println("Converted text:", text)
	}
}
